/* Support destinations are kept in one small, editable object. The renderer
   only accepts the expected HTTPS hosts, so a typo cannot create an unsafe
   outbound link. */
window.CUBE_SUPPORT={coffee:"https://buymeacoffee.com/manavbuilds",x:"https://x.com/Manavdoedits",linkedin:"https://www.linkedin.com/in/manavsharma-/"};
window.renderSupport=function(){const icons={x:'<path d="M18.9 2H22l-6.8 7.8L23.2 22h-6.3L12 14.6 5.5 22H2.3l8.2-9.4L.8 2h6.5l4.4 6.7L18.9 2zm-1.1 18h1.7L6.3 4H4.5z" fill="currentColor"/>',linkedin:'<path d="M5 8H2v14h3zM3.5 2a2 2 0 1 0 0 4 2 2 0 0 0 0-4zM9 8v14h3V14c0-4 6-4 6 0v8h3v-9c0-6-7-6-9-3V8z" fill="currentColor"/>'};const host={coffee:['buymeacoffee.com','www.buymeacoffee.com'],x:['x.com','www.x.com'],linkedin:['linkedin.com','www.linkedin.com']};const labels={coffee:'Support this project',x:'X',linkedin:'LinkedIn'};const nav=document.getElementById('support-links');nav.replaceChildren();for(const key of Object.keys(labels)){let u;try{u=new URL(window.CUBE_SUPPORT[key]);}catch{continue;}if(u.protocol!=='https:'||!host[key].includes(u.hostname))continue;const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label',`${labels[key]} on ${key==='coffee'?'Buy Me a Coffee':labels[key]} — opens in a new tab`);a.innerHTML=key==='coffee'?'<img class="coffee-button-icon" src="assets/cube-easy/coffee.svg" alt="" aria-hidden="true">':`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>`;nav.append(a);}nav.hidden=!nav.children.length;};
